package com.yonlab.vision;
import android.content.Context;import java.io.*;import java.util.*;import org.json.*;
/** Evaluates only publisher/synthetic references bound to the actual encoded input SHA. */
final class ExpansionTruth {
 private ExpansionTruth(){}private static Map<String,JSONObject> catalog;
 private static synchronized JSONObject item(Context c,String id)throws Exception{if(catalog==null){Map<String,JSONObject> all=new HashMap<>();try(InputStream in=c.getAssets().open("one/demos.json")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(b.size()+n>4*1024*1024)throw new IOException("catalog");b.write(block,0,n);}JSONArray rows=new JSONObject(b.toString("UTF-8")).getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);all.put(row.getString("id"),row);}}catalog=all;}return catalog.get(id);}
 static void apply(Context c,String demo,String inputSha,OneModelRunner.Result r){if(demo==null||demo.isEmpty()||!"COMPLETED".equals(r.state))return;
  try{JSONObject source=item(c,demo);if(source==null||!source.getString("sha256").equals(inputSha))return;JSONObject q=new JSONObject().put("referenceVerified",true).put("referenceInputSha256",inputSha).put("difficulty",source.optString("difficulty","")).put("conditions",source.optJSONArray("conditions")==null?new JSONArray():source.getJSONArray("conditions"));
   if("document".equals(r.feature)&&source.has("documentExpected")&&source.optBoolean("referenceVerified")){
    JSONObject expected=source.getJSONObject("documentExpected"),fields=new JSONObject();int n=0,exact=0;for(String key:new String[]{"merchant","date","total","currency"}){String target=expected.optString(key,"");if(target.isEmpty())continue;String actual=r.metrics.optString(key,"");boolean correct=ExpansionQualityMath.sameField(key,actual,target);if(correct)exact++;n++;fields.put(key,new JSONObject().put("expected",target).put("actual",actual).put("exact",correct));}
    q.put("type","DOCUMENT_FIELDS").put("fieldExact",n==0?JSONObject.NULL:exact/(double)n).put("exactFields",exact).put("expectedFields",n).put("fields",fields).put("referenceKind","AUTHOR_WRITTEN_FICTIONAL_DOCUMENT");String reference=source.optString("reference","");String ocr=r.metrics.optString("recognizedText","");if(ocr.isEmpty())ocr=r.detail;/* Raw OCR is preferred; field summary is never used as a reconstructed reference. */
    if(r.metrics.has("recognizedText")&&!ExpansionQualityMath.text(reference).isEmpty())q.put("CER",ExpansionQualityMath.cer(reference,r.metrics.getString("recognizedText"))).put("textPolicy","NFKC case-insensitive; whitespace/punctuation ignored; edit-distance/reference characters");
   }else if("qr".equals(r.feature)&&source.has("qrExpected")){
    JSONObject expected=source.getJSONObject("qrExpected");if(!expected.optBoolean("verified"))return;String text=expected.getString("text"),format=expected.getString("format");boolean exact=false;JSONArray codes=r.metrics.optJSONArray("codes");if(codes!=null){for(int i=0;i<codes.length();i++){JSONObject code=codes.getJSONObject(i);if(text.equals(code.optString("value"))&&format.equals(code.optString("format")))exact=true;}}else exact=text.equals(r.detail)&&format.equals(r.metrics.optString("format"));q.put("type","QR_DECODE").put("fieldExact",exact?1d:0d).put("exactMatched",exact).put("expectedFormat",format).put("expectedCharacters",text.length()).put("sourceCreatorScriptSha256",expected.optString("sourceCreatorScriptSha256")).put("scope","AUTHOR_ENCODED_PAYLOAD_AND_FORMAT; literal Unicode match; degraded pixels never redefine the reference");
   }else if("search".equals(r.feature)&&source.has("retrievalExpectedIds")){
    JSONArray expected=source.getJSONArray("retrievalExpectedIds");Set<String> ids=new HashSet<>();for(int i=0;i<expected.length();i++)ids.add(expected.getString(i));JSONArray ranking=r.metrics.getJSONArray("ranking");List<String> ranked=new ArrayList<>();for(int i=0;i<ranking.length();i++)ranked.add(ranking.getJSONObject(i).getString("id"));if(ids.isEmpty())return;q.put("type","IMAGE_RETRIEVAL").put("top1",!ranked.isEmpty()&&ids.contains(ranked.get(0))).put("top3",ranked.subList(0,Math.min(3,ranked.size())).stream().anyMatch(ids::contains)).put("mrr",ExpansionQualityMath.reciprocalRank(ranked,ids)).put("expectedIds",expected).put("scope","KNOWN_SOURCE_DERIVATIVE_QUERY_TO_FIXED_GALLERY");
   }else if(("coach".equals(r.feature)||"pose".equals(r.feature))&&source.has("groundTruthPose")&&r.metrics.has("points")){
    JSONObject expected=source.getJSONObject("groundTruthPose");if(!"COCO17".equals(expected.optString("layout")))return;JSONArray truth=expected.getJSONArray("keypoints"),box=expected.getJSONArray("personBbox"),pred=r.metrics.getJSONArray("points");if(truth.length()!=51)return;Map<Integer,JSONObject> points=new HashMap<>();for(int i=0;i<pred.length();i++){JSONObject v=pred.getJSONObject(i);points.put(v.getInt("id"),v);}int labeled=0,correct=0;double w=expected.getDouble("sourceWidth"),h=expected.getDouble("sourceHeight"),threshold=.1*Math.max(box.getDouble(2),box.getDouble(3));int[] mapping=OneTensorMath.cocoToMlKit();for(int i=0;i<17;i++){if(truth.getInt(i*3+2)<=0)continue;labeled++;JSONObject p=points.get(mapping[i]);if(p==null||p.optDouble("score",p.optDouble("likelihood",0))<.5)continue;double x=p.getDouble("x")*w,y=p.getDouble("y")*h;if(Math.hypot(x-truth.getDouble(i*3),y-truth.getDouble(i*3+1))<=threshold)correct++;}if(labeled==0)return;q.put("type","POSE_PCK").put("PCK",correct/(double)labeled).put("correct",correct).put("labeled",labeled).put("thresholdPixels",threshold).put("policy","PCK@0.1 max annotated-person bbox dimension; largest annotated person; v>0 labeled; confidence>=0.5").put("annotatedPeople",expected.optInt("annotatedPeople",1));
   }else return;r.metrics.put("verifiedTaskEvaluation",q);
  }catch(Exception e){try{r.metrics.put("taskEvaluationState","INVALID_REFERENCE_OR_OUTPUT");}catch(JSONException ignored){}}
 }
}
